import pandas as pd
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded character-prefix layout optimizer with prototype-aligned row permutations."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize a scalar like the evaluator, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using bounded binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact Trie reuse as LCP lengths of lexicographically adjacent strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested merge groups contiguous while preserving proposed group order."""
        if not col_merge:
            return list(order)

        positions = {column: index for index, column in enumerate(order)}
        owners = {}
        claimed = set()

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Apply merge constraints and return a valid integer column permutation."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row using its supplied row-specific column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build frequency-ranked and repeated-pair global column orders."""
        rows = len(text)
        width = len(columns)
        statistics = []

        for column in range(width):
            counts = {}
            for row in range(rows):
                value = text[row][column]
                counts[value] = counts.get(value, 0) + 1

            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            statistics.append((pair_mass, len(counts)))

        ranked = sorted(
            range(width),
            key=lambda column: (
                -statistics[column][0],
                statistics[column][1],
                column,
            ),
        )

        first = self._normalize(columns, ranked, col_merge)

        examined = ranked[:min(28, width)]
        pair_scores = []

        for left in examined:
            for right in examined:
                if left == right:
                    continue

                counts = {}
                for row in range(rows):
                    value = text[row][left] + text[row][right]
                    counts[value] = counts.get(value, 0) + 1

                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                if score:
                    pair_scores.append((-score, left, right))

        pair_scores.sort()
        used = set()
        paired = []

        for _, left, right in pair_scores:
            if left in used or right in used:
                continue
            paired.extend((left, right))
            used.add(left)
            used.add(right)

        paired.extend(column for column in ranked if column not in used)
        second = self._normalize(columns, paired, col_merge)
        return [first, second], ranked

    def _prototype_candidate(self, text, columns, col_merge, base_order):
        """Align rows to up to four diverse row prototypes and greedily match their prefixes."""
        rows = len(text)
        width = len(columns)
        fallback = self._normalize(columns, base_order, col_merge)

        if rows < 2 or width < 2:
            return [fallback[:] for _ in range(rows)]

        sample_rows = list(range(min(rows, 256)))
        sample_order = base_order[:min(width, 32)]

        # Initial prototype strings use the reliable global frequency ordering.
        prototype_strings = [
            "".join(text[row][column] for column in sample_order)
            for row in sample_rows
        ]

        # Select diverse actual rows by maximizing distance from selected prototypes.
        anchors = [sample_rows[0]]
        anchor_strings = [prototype_strings[0]]

        while len(anchors) < min(4, len(sample_rows)):
            best_row = None
            best_distance = -1

            for position, row in enumerate(sample_rows):
                if row in anchors:
                    continue

                candidate = prototype_strings[position]
                nearest = max(
                    self._lcp(candidate, prototype)
                    for prototype in anchor_strings
                )
                distance = len(candidate) - nearest

                if distance > best_distance:
                    best_distance = distance
                    best_row = row

            if best_row is None:
                break

            anchors.append(best_row)
            anchor_strings.append(
                "".join(text[best_row][column] for column in sample_order)
            )

        def assign(current_strings):
            """Assign each sampled row to the anchor with the longest character prefix."""
            assignments = []
            for value in current_strings:
                best = 0
                best_score = -1
                for index, prototype in enumerate(anchor_strings):
                    score = self._lcp(value, prototype)
                    if score > best_score:
                        best_score = score
                        best = index
                assignments.append(best)
            return assignments

        def build(assignments):
            """Construct row orders by greedily matching fields to assigned prototypes."""
            result = [fallback[:] for _ in range(rows)]

            for sample_index, row in enumerate(sample_rows):
                prototype = anchor_strings[assignments[sample_index]]
                remaining = list(sample_order)
                chosen = []
                cursor = 0

                while remaining:
                    best_column = remaining[0]
                    best_score = -1

                    for column in remaining:
                        score = self._lcp(
                            text[row][column],
                            prototype[cursor:],
                        )
                        if score > best_score:
                            best_score = score
                            best_column = column

                    chosen.append(best_column)
                    cursor += len(text[row][best_column])
                    remaining.remove(best_column)

                tail = [column for column in base_order if column not in chosen]
                result[row] = self._normalize(
                    columns,
                    chosen + tail,
                    col_merge,
                )

            return result

        # Two bounded alignment rounds: initial global assignment, then reassignment
        # using the strings generated by the first prototype-specific construction.
        current = prototype_strings
        assignments = assign(current)
        result = build(assignments)

        generated = [
            "".join(text[row][column] for column in result[row])
            for row in sample_rows
        ]
        assignments = assign(generated)
        return build(assignments)

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded global or prototype-aligned layout by exact Trie reuse."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_candidates, base_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []
        for order in global_candidates:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((self._reuse(serialized), orders, serialized))

        prototype_orders = self._prototype_candidate(
            text,
            columns,
            col_merge,
            base_order,
        )
        prototype_serialized = self._serialize(text, prototype_orders)
        candidates.append((
            self._reuse(prototype_serialized),
            prototype_orders,
            prototype_serialized,
        ))

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings
